# Let me manually analyze the differences first
inputs = ['izvfvc', 'gfgdc', 'ic', 'gfv', 'cfyu']
outputs = ['izhfhczc', 'czcuzxuzdczc', 'iczc', 'czcuzfh', 'czcfxxiu']

print("Analyzing differences:")
for i in range(len(inputs)):
    print(f"\n{i}: '{inputs[i]}' -> '{outputs[i]}'")
    # Let's look at character by character differences
    in_str = inputs[i]
    out_str = outputs[i]

    # Find where they differ
    diff_positions = []
    for j in range(min(len(in_str), len(out_str))):
        if in_str[j] != out_str[j]:
            diff_positions.append((j, in_str[j], out_str[j]))

    if len(out_str) > len(in_str):
        for j in range(len(in_str), len(out_str)):
            diff_positions.append((j, '_', out_str[j]))
    elif len(in_str) > len(out_str):
        for j in range(len(out_str), len(in_str)):
            diff_positions.append((j, in_str[j], '_'))

    print(f"  Differences at positions: {diff_positions}")

